historical_supplementary_runtime.script:
import assert from 'node:assert/strict';
import { agent } from '@ax-llm/ax';
import { scriptedAI } from './support.ts';
let httpCalls = 0;
globalThis.fetch = async () => { httpCalls++; throw new Error('External HTTP forbidden in this proof'); };
const marker = 'AX411_STATIC_FORWARD_SKILL_ONLY_7df86c';
const results = [];
for (const preload of [false, true]) {
  const stages = [];
  let seen = false;
  let promptSha;
  const { createHash } = await import('node:crypto');
  const distiller = scriptedAI(request => {
    stages.push('distiller');
    const prompt = JSON.stringify(request.chatPrompt);
    seen = prompt.includes(marker);
    promptSha = createHash('sha256').update(prompt).digest('hex');
    return { results: [{ index: 0, content: JSON.stringify({ javascriptCode:
      `await respond("Report guide visibility", { visible: ${seen} });` }), finishReason: 'stop' }] };
  }, { structuredOutputs: true });
  const executor = scriptedAI(() => { stages.push('executor'); throw new Error('Static direct response must omit executor'); });
  const responder = scriptedAI(() => {
    stages.push('responder');
    return { results: [{ index: 0, content: `Answer: ${seen ? 'visible' : 'absent'}`, finishReason: 'stop' }] };
  });
  const worker = agent('task:string -> answer:string', {
    contextFields: [], contextOptions: { ai: distiller }, executorOptions: { ai: executor }, responderOptions: { ai: responder },
  });
  try {
    const output = await worker.forward(executor, { task: 'Report guide availability.' }, {
      maxRetries: 0,
      ...(preload ? { skills: [{ id: 'skill:static', name: 'Static guide', content: marker }] } : {}),
    });
    assert.equal(seen, preload);
    assert.equal(output.answer, preload ? 'visible' : 'absent');
    assert.deepEqual(stages, ['distiller', 'responder']);
    results.push({ preload, distillerMarkerObserved: seen, stages, output, promptSha });
  } finally { worker.stop(); }
}
assert.equal(httpCalls, 0);
console.log(JSON.stringify({ results, httpCalls, proof: 'Actual SDK static direct-respond prompt ingestion; scripted I/O, not model reliance or quality.' }));

